import unittest

from hourglass.models import Span
from hourglass.rounding import round_span, rounded_labels


class StepTests(unittest.TestCase):
    def test_zero_step_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(540, 600)], 0)

    def test_negative_step_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(540, 600)], -15)

    def test_uneven_step_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(540, 600)], 7)


class RoundTests(unittest.TestCase):
    def test_start_rounds_down(self):
        self.assertEqual(round_span(Span(541, 600), 15).start, 540)

    def test_end_rounds_up(self):
        self.assertEqual(round_span(Span(540, 1019), 15).end, 1020)

    def test_tie_rounds_up(self):
        self.assertEqual(round_span(Span(532, 600), 15).start, 540)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 543), 15)


class LabelTests(unittest.TestCase):
    def test_label(self):
        labels = rounded_labels([Span(541, 1034)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])
